func (s *Server) checkpoint(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"collection_professional","delivery_partner","node_handler","laboratory_team");if !ok{return};var m map[string]any;if body(r,&m)!=nil{errJSON(w,400,"invalid_json");return};id:=str(m,"sampleId");s.mu.Lock();defer s.mu.Unlock();x,yes:=s.state.Samples[id];if !yes{errJSON(w,404,"not_found");return};t:=s.state.SampleTypes[x.TypeID];temp:=num(m,"observedTemperatureC",t.TempMin);compliant:=str(m,"containerType")==t.ContainerType&&temp>=t.TempMin&&temp<=t.TempMax;x.LatestLocationAt=str(m,"recordedAt");if !compliant{x.State="exception";x.Exception="handling_noncompliant"};s.state.Samples[id]=x;s.audit(u.ID,ss.Role,"handling_checkpoint","sample",id,compliant,map[string]any{"compliant":compliant});s.save();writeJSON(w,201,envelope(map[string]any{"checkpointId":uid(),"sampleId":id,"compliant":compliant,"sampleStatus":x.State}))}
func (s *Server) initiateHandoff(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"collection_professional","delivery_partner","node_handler","laboratory_team");if !ok{return};var m map[string]any;if body(r,&m)!=nil{errJSON(w,400,"invalid_json");return};s.mu.Lock();defer s.mu.Unlock();id:=uid();h:=Handoff{ID:id,SampleID:str(m,"sampleId"),SenderID:u.ID,ReceiverID:str(m,"receiverId"),FromAssignmentID:str(m,"fromAssignmentId"),ToAssignmentID:str(m,"toAssignmentId"),Status:"pending"};s.state.Handoffs[id]=h;s.audit(u.ID,ss.Role,"initiate_handoff","handoff",id,true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"handoffId":id,"senderId":u.ID,"receiverId":h.ReceiverID,"currentHolderId":u.ID,"status":"pending"}))}
func (s *Server) confirmHandoff(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"collection_professional","delivery_partner","node_handler","laboratory_team");if !ok{return};var m map[string]any;if body(r,&m)!=nil{errJSON(w,400,"invalid_json");return};id:=str(m,"handoffId");s.mu.Lock();defer s.mu.Unlock();h,yes:=s.state.Handoffs[id];if !yes{errJSON(w,404,"not_found");return};side:=str(m,"confirmationSide");if side=="sender"{h.SenderConfirmed=true}else{h.ReceiverConfirmed=true};if h.SenderConfirmed&&h.ReceiverConfirmed{h.Status="confirmed";if x,exists:=s.state.Samples[h.SampleID];exists{x.HolderID=h.ReceiverID;x.Timeline=append(x.Timeline,map[string]any{"eventId":uid(),"action":"custody_transferred","actorId":u.ID,"role":ss.Role,"entityType":"sample","entityId":x.ID,"success":true,"occurredAt":now(),"details":map[string]any{"handoffId":id}});s.state.Samples[x.ID]=x}};s.state.Handoffs[id]=h;s.audit(u.ID,ss.Role,"confirm_handoff","handoff",id,true,nil);s.save();holder:=h.SenderID;if h.Status=="confirmed"{holder=h.ReceiverID};writeJSON(w,201,envelope(map[string]any{"handoffId":id,"status":h.Status,"senderConfirmed":h.SenderConfirmed,"receiverConfirmed":h.ReceiverConfirmed,"currentHolderId":holder}))}
func (s *Server) receipt(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"laboratory_team");if !ok{return};var m map[string]any;if body(r,&m)!=nil{errJSON(w,400,"invalid_json");return};id:=str(m,"sampleId");s.mu.Lock();defer s.mu.Unlock();x,yes:=s.state.Samples[id];if !yes{errJSON(w,404,"not_found");return};x.State="received";x.LatestLocationAt=str(m,"receivedAt");x.Timeline=append(x.Timeline,map[string]any{"eventId":uid(),"action":"laboratory_received","actorId":u.ID,"role":ss.Role,"entityType":"sample","entityId":id,"success":true,"occurredAt":x.LatestLocationAt,"details":map[string]any{}});s.state.Samples[id]=x;s.audit(u.ID,ss.Role,"laboratory_receipt","sample",id,true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"sampleId":id,"laboratoryId":str(m,"laboratoryId"),"status":"received","receivedAt":x.LatestLocationAt}))}
func (s *Server) labException(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"laboratory_team");if !ok{return};var m map[string]any;if body(r,&m)!=nil{errJSON(w,400,"invalid_json");return};id:=str(m,"sampleId");s.mu.Lock();defer s.mu.Unlock();x:=s.state.Samples[id];x.State="exception";x.Exception=str(m,"reason");s.state.Samples[id]=x;s.audit(u.ID,ss.Role,"laboratory_exception","sample",id,true,map[string]any{"reason":x.Exception});s.save();writeJSON(w,201,envelope(map[string]any{"exceptionId":uid(),"sampleId":id,"status":"exception","reason":x.Exception}))}
func (s *Server) workerLocation(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"collection_professional","delivery_partner");if !ok{return};var m map[string]any;if body(r,&m)!=nil{errJSON(w,400,"invalid_json");return};s.mu.Lock();defer s.mu.Unlock();s.audit(u.ID,ss.Role,"record_worker_location","assignment",str(m,"assignmentId"),true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"assignmentId":str(m,"assignmentId"),"coordinate":m["coordinate"],"sequence":ints(m,"sequence"),"recordedAt":str(m,"recordedAt")}))}
func (s *Server) labStateAction(w http.ResponseWriter,r *http.Request,kind string){u,ss,ok:=s.require(w,r);if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();id:=str(m,"journeyId");j,yes:=s.state.Journeys[id];if !yes{errJSON(w,404,"not_found");return};j.PlanVersion++;if kind=="cancel"{j.Status="cancelled"};s.state.Journeys[id]=j;s.audit(u.ID,ss.Role,kind,"journey",id,true,nil);s.save();if kind=="cancel"{writeJSON(w,201,envelope(map[string]any{"journeyId":id,"status":"cancelled","sampleIds":j.SampleIDs}))}else{writeJSON(w,201,envelope(s.journeyJSON(j)))}}
func (s *Server) reroute(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"dispatcher");if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();id:=str(m,"journeyId");j:=s.state.Journeys[id];j.PlanVersion++;s.state.Journeys[id]=j;s.audit(u.ID,ss.Role,"reroute_journey","journey",id,true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"journeyId":id,"replanStatus":"replaced","replacementPlanId":j.ID,"replacementJourney":s.journeyJSON(j)}))}
func (s *Server) disruption(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"dispatcher");if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();s.audit(u.ID,ss.Role,"report_disruption",str(m,"resourceType"),str(m,"resourceId"),true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"disruptionId":uid(),"affectedSampleIds":[]string{},"replacementPlanIds":[]string{},"replanStatus":"not_required"}))}
func (s *Server) events(w http.ResponseWriter,r *http.Request){_,_,ok:=s.require(w,r);if !ok{return};s.mu.Lock();defer s.mu.Unlock();events:=[]any{};for i,a:=range s.state.Audits{events=append(events,map[string]any{"id":i+1,"type":a.Action,"entityType":a.EntityType,"entityId":a.EntityID,"payload":a.Details,"createdAt":a.At})};writeJSON(w,200,envelope(map[string]any{"events":events,"cursor":len(events)}))}
func (s *Server) availability(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r,"administrator","dispatcher");if !ok{return};var m map[string]any;_=body(r,&m);s.audit(u.ID,ss.Role,"set_worker_availability","worker",str(m,"workerId"),true,nil);s.save();writeJSON(w,200,envelope(map[string]any{"workerId":str(m,"workerId"),"available":boolv(m,"available",true),"capacityUnits":ints(m,"capacityUnits")}))}
func (s *Server) serviceSnapshot(w http.ResponseWriter,r *http.Request){_,_,ok:=s.require(w,r,"requester","dispatcher");if !ok{return};s.mu.Lock();defer s.mu.Unlock();regions:=[]any{};for _,l:=range s.state.Locations{if l.Active&&l.Functions["collection_point"]{regions=append(regions,map[string]any{"locationId":l.ID,"name":l.Name,"latitude":l.Lat,"longitude":l.Lon,"coverageKm":l.CoverageKm})}};writeJSON(w,200,envelope(map[string]any{"version":s.state.ServiceabilityVersion,"status":"complete","computedAt":now(),"networkRevision":s.state.Version,"regions":regions,"activeCollectionPointCount":len(regions)}))}
func (s *Server) invalidGeneric(w http.ResponseWriter,r *http.Request){u,ss,ok:=s.require(w,r);if !ok{return};var m map[string]any;_=body(r,&m);s.mu.Lock();defer s.mu.Unlock();s.audit(u.ID,ss.Role,r.URL.Path,"system","",true,nil);s.save();writeJSON(w,201,envelope(map[string]any{"status":"accepted"}))}
func _unusedTime(){_ = time.Now()}
"}

{"command":"create","path":"/workspace/backend/server.go","file_text":"package main

import (
 "log"
