{"command":"create","path":"/workspace/frontend/src/main.tsx","file_text":"import React, {useEffect, useState} from 'react';
import {createRoot} from 'react-dom/client';
import './style.css';

type Any = Record<string, any>;
const api = async (path:string, options:RequestInit={}) => { const token=localStorage.getItem('sessionToken'); const headers:any={'Content-Type':'application/json',...(options.headers||{})}; if(token)headers.Authorization=`Bearer ${token}`; const res=await fetch(path,{...options,headers}); const data=await res.json().catch(()=>({})); if(!res.ok)throw new Error(data.error||data.code||'Request failed'); return data.data??data; };
const post=(p:string,b:Any={})=>api(p,{method:'POST',body:JSON.stringify(b)});
const fmt=(v:any)=>v?new Date(v).toLocaleString(): '—';
const statusLabel=(v:string)=>v?.replaceAll('_',' ')||'unknown';

function Login({onLogin}:{onLogin:()=>void}) { const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();try{const x=await post('/api/authenticate-user',{username,password});localStorage.setItem('sessionToken',x.sessionToken);onLogin()}catch(e:any){setError(e.message)}};return <main className="login"><div className="login-card"><div className="brand-mark">◈</div><p className="eyebrow">CLINICAL LOGISTICS</p><h1>Sample journey control</h1><p className="muted">Secure pickup, custody and laboratory delivery.</p><form onSubmit={submit}><label>Username<input aria-label="Username" value={username} onChange={e=>setUsername(e.target.value)} required autoComplete="username"/></label><label>Password<input aria-label="Password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required autoComplete="current-password"/></label>{error&&<div role="alert" className="error">{error}</div>}<button className="primary" type="submit">Sign in securely</button></form></div></main> }

function App(){const [boot,setBoot]=useState<Any|null>(null);const [tab,setTab]=useState('Overview');const [toast,setToast]=useState('');const [showLogin,setShowLogin]=useState(false);const load=()=>api('/api/ui/bootstrap').then(setBoot).catch(()=>setShowLogin(true));useEffect(()=>{load()},[]);if(showLogin||!boot)return <Login onLogin={()=>{setShowLogin(false);load()}}/>;const user=boot.user;const role=user.activeRole;const refresh=()=>load();const signOut=()=>{localStorage.removeItem('sessionToken');setShowLogin(true);setBoot(null)};const notify=(s:string)=>{setToast(s);setTimeout(()=>setToast(''),3500)};const switchRole=async(e:React.ChangeEvent<HTMLSelectElement>)=>{try{await post('/api/select-active-role',{role:e.target.value});refresh()}catch(e:any){notify(e.message)}};return <div className="shell"><aside><div className="logo"><span>◈</span><div>LAB<span>FLOW</span></div></div><div className="user-mini"><div className="avatar">{(user.fullName||user.username)[0]}</div><div><strong>{user.fullName||user.username}</strong><small>{role.replaceAll('_',' ')}</small></div></div><nav aria-label="Main navigation">{['Overview','My work','Samples','Live map','Audit trail'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{icon(x)}<span>{x}</span></button>)}</nav><div className="aside-bottom"><label className="role-select">Working as<select aria-label="Active role" value={role} onChange={switchRole}>{user.roles.map((r:string)=><option key={r}>{r}</option>)}</select></label><button className="signout" onClick={signOut}>↪ Sign out</button></div></aside><main className="content"><header><div><p className="eyebrow">OPERATIONS CENTER / {role.replaceAll('_',' ').toUpperCase()}</p><h1>{tab}</h1></div><div className="header-actions"><span className="live-dot">● Live</span><button className="icon-btn" aria-label="Refresh" onClick={refresh}>↻</button></div></header>{toast&&<div className="toast">{toast}</div>}{tab==='Overview'&&<Overview boot={boot} role={role} setTab={setTab}/>} {tab==='My work'&&<Work role={role} notify={notify}/>} {tab==='Samples'&&<Samples boot={boot} role={role} notify={notify}/>} {tab==='Live map'&&<Map boot={boot}/>} {tab==='Audit trail'&&<Audit notify={notify}/>}</main></div>}
function icon(x:string){return <span className="nav-icon">{({Overview:'⌂','My work':'✓',Samples:'◉','Live map':'⌖','Audit trail':'≋'} as Any)[x]}</span>}
function Overview({boot,role,setTab}:{boot:Any,role:string,setTab:(s:string)=>void}){const op=boot.operations;const samples=boot.requesterSamples||[];const all=op?.samples||samples;return <><section className="hero"><div><p className="eyebrow">TODAY'S NETWORK PULSE</p><h2>Every sample, accounted for.</h2><p>Monitor custody, capacity and delivery confidence across your active network.</p></div><button className="primary" onClick={()=>setTab('Samples')}>＋ New collection request</button></section><div className="metrics"><Metric label="Active samples" value={all.length} trend="Across your permitted view"/><Metric label="In transit" value={all.filter((x:Any)=>['in_transit','sealed'].includes(x.state||x.status)).length} trend="Live custody updates"/><Metric label="Exceptions" value={(op?.exceptions||[]).length} trend="Needs attention" danger/><Metric label="Network status" value="Ready" trend="All services operational" good/></div><div className="grid-two"><section className="panel"><div className="panel-head"><div><p className="eyebrow">RECENT ACTIVITY</p><h3>Status timeline</h3></div><button className="text-btn" onClick={()=>setTab('Samples')}>View all →</button></div>{all.length===0?<Empty title="No sample activity yet" text="Create a collection request to start a tracked journey."/>:<div className="activity">{all.slice(0,5).map((x:Any)=><div className="activity-row" key={x.sampleId}><span className="timeline-dot"/><div><strong>Sample {x.sampleId.slice(0,8)}</strong><p>{statusLabel(x.state||x.status)} · updated {fmt(x.locationRecordedAt)}</p></div><span className="badge">{statusLabel(x.state||x.status)}</span></div>)}</div>}</section><section className="panel network-card"><div className="panel-head"><div><p className="eyebrow">NETWORK</p><h3>Serviceability</h3></div><span className="pill green">● Live</span></div><div className="network-graphic"><div className="network-line l1"/><div className="network-line l2"/><span className="node n1">⌂</span><span className="node n2">◆</span><span className="node n3">▣</span><span className="map-label">Active collection coverage</span></div><div className="legend"><span><i className="dot cyan"/> Collection points</span><span><i className="dot orange"/> Laboratories</span></div></section></div></>}
function Metric({label,value,trend,danger,good}:{label:string,value:any,trend:string,danger?:boolean,good?:boolean}){return <div className="metric"><span className="metric-label">{label}</span><strong className={danger?'danger':good?'good':''}>{value}</strong><small>{trend}</small></div>}
function Empty({title,text}:{title:string,text:string}){return <div className="empty"><div>◌</div><strong>{title}</strong><p>{text}</p></div>}
function Work({role,notify}:{role:string,notify:(s:string)=>void}){const [work,setWork]=useState<Any>({pending:[],inProgress:[],completed:[]});useEffect(()=>{post('/api/list-role-work',{role}).then(setWork).catch(e=>notify(e.message))},[role]);const accept=async(id:string)=>{try{await post('/api/accept-assignment',{assignmentId:id,idempotencyKey:crypto.randomUUID()});notify('Assignment accepted');setWork(await post('/api/list-role-work',{role}))}catch(e:any){notify(e.message)}};return <><section className="section-intro"><p className="eyebrow">ROLE QUEUE</p><h2>Your work, with custody context.</h2><p>Offers, active assignments, and completed work are separated for this role.</p></section><div className="work-columns"><WorkColumn title="Pending offers" items={work.pending||[]} onAccept={accept}/><WorkColumn title="In progress" items={work.inProgress||[]}/><WorkColumn title="Completed" items={work.completed||[]} done/></div></>}
function WorkColumn({title,items,onAccept,done}:{title:string,items:Any[],onAccept?:(id:string)=>void,done?:boolean}){return <section className="panel work-col"><div className="panel-head"><h3>{title}</h3><span className="count">{items.length}</span></div>{items.length===0?<Empty title="Nothing here" text="New work will appear here."/>:items.map(x=><div className="work-card" key={x.assignmentId||x.sampleId}><div className="work-top"><span className="badge">{x.kind}</span><span className="muted">{x.assignmentId?.slice(0,8)||x.sampleId?.slice(0,8)}</span></div><strong>Sample {x.sampleId?.slice(0,12)}</strong><p>{x.fromLocationId?'Transport leg':'Collection task'} · {statusLabel(x.status)}</p>{onAccept&&<button className="secondary" onClick={()=>onAccept(x.assignmentId)}>Accept assignment</button>}</div>)}</section>}
function Samples({boot,role,notify}:{boot:Any,role:string,notify:(s:string)=>void}){const [show,setShow]=useState(false);const [selected,setSelected]=useState<Any>();const samples=boot.requesterSamples||boot.operations?.samples||[];return <><section className="section-intro split"><div><p className="eyebrow">CUSTODY LEDGER</p><h2>Sample journeys</h2><p>Follow current holder, route progress, and the full ordered status history.</p></div>{role==='requester'&&<button className="primary" onClick={()=>setShow(true)}>＋ New request</button>}</section>{samples.length===0?<section className="panel"><Empty title="No samples found" text="Your permitted sample ledger is empty."/></section>:<section className="panel table-panel"><table><thead><tr><th>Sample</th><th>Status</th><th>Custodian</th><th>Last update</th><th>Freshness</th><th/></tr></thead><tbody>{samples.map((x:Any)=><tr key={x.sampleId}><td><strong>{x.sampleId.slice(0,12)}</strong><small>{x.requestId?.slice(0,12)}</small></td><td><span className="badge">{statusLabel(x.state)}</span></td><td>{x.currentHolderId?.slice(0,10)||'Unassigned'}</td><td>{fmt(x.locationRecordedAt)}</td><td><span className={x.locationStale?'stale':'fresh'}>{x.locationStale?'Stale':'Fresh'}</span></td><td><button className="text-btn" onClick={()=>setSelected(x)}>View →</button></td></tr>)}</tbody></table></section>}{selected&&<SampleDrawer sample={selected} close={()=>setSelected(undefined)}/>} {show&&<RequestForm close={()=>setShow(false)} notify={notify}/>}</>}
function SampleDrawer({sample,close}:{sample:Any,close:()=>void}){return <div className="drawer-backdrop" onClick={close}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="close" onClick={close}>×</button><p className="eyebrow">SAMPLE TIMELINE</p><h2>{sample.sampleId.slice(0,16)}</h2><div className="drawer-status"><span className="badge">{statusLabel(sample.state)}</span><span className={sample.locationStale?'stale':'fresh'}>{sample.locationStale?'Location stale':'Location fresh'}</span></div><div className="detail-grid"><span>Current holder</span><strong>{sample.currentHolderId||'Not assigned'}</strong><span>Last known location</span><strong>{sample.latestLocation?.name||sample.originType||'Origin'}</strong><span>Delivery deadline</span><strong>{fmt(sample.deliveryDeadline)}</strong></div><h3>Status history</h3><div className="drawer-timeline">{(sample.timeline||[]).map((e:Any)=><div key={e.eventId}><i/><div><strong>{statusLabel(e.action)}</strong><small>{fmt(e.occurredAt)}</small></div></div>)}</div></aside></div>}
function RequestForm({close,notify}:{close:()=>void,notify:(s:string)=>void}){const [type,setType]=useState('');const [deadline,setDeadline]=useState('');const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await post('/api/create-collection-request',{origin:{latitude:0,longitude:0},originType:'home',requestedAt:new Date().toISOString(),deliveryDeadline:new Date(deadline).toISOString(),sampleTypeId:type,containerType:'standard',temperatureMinC:15,temperatureMaxC:25,earliestCollectionAt:new Date().toISOString(),latestCollectionAt:deadline,idempotencyKey:crypto.randomUUID()});notify('Collection request created');close()}catch(e:any){setError(e.message)}};return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><button type="button" className="close" onClick={close}>×</button><p className="eyebrow">NEW REQUEST</p><h2>Plan a collection</h2><label>Sample type<select value={type} onChange={e=>setType(e.target.value)} required><option value="">Select a type</option><option value="amber">Amber</option><option value="indigo">Indigo</option><option value="frost">Frost</option><option value="pulse">Pulse</option></select></label><label>Delivery deadline<input type="datetime-local" value={deadline} onChange={e=>setDeadline(e.target.value)} required/></label>{error&&<div className="error">{error}</div>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary">Check & create</button></div></form></div>}
function Map({boot}:{boot:Any}){const locs=boot.operations?.locations||[];return <><section className="section-intro"><p className="eyebrow">LIVE NETWORK VIEW</p><h2>Map & network health</h2><p>Local map assets only · worker and facility locations are scoped to your permissions.</p></section><section className="map-panel"><div className="map-surface"><div className="map-grid"/><div className="map-water"/><span className="map-compass">N<br/>↑</span>{locs.map((l:Any,i:number)=><div className="map-node" style={{left:`${25+(i*23)%65}%`,top:`${30+(i*17)%50}%`}} key={l.locationId}><span>{l.functions?.laboratory?'▣':'◆'}</span><b>{l.name}</b></div>)}<div className="map-attribution">Local PMTiles · MapLibre-compatible view</div></div><div className="map-sidebar"><p className="eyebrow">LOCATIONS</p>{locs.length?locs.map((l:Any)=><div className="location-item" key={l.locationId}><span className="dot cyan"/><div><strong>{l.name}</strong><small>{Object.keys(l.functions||{}).filter(k=>l.functions[k]).join(' · ')}</small></div><span className="pill green">Active</span></div>):<Empty title="No locations configured" text="An administrator can add network locations."/>}</div></section></>}
function Audit({notify}:{notify:(s:string)=>void}){const [entries,setEntries]=useState<Any[]>([]);const [query,setQuery]=useState('');const search=()=>post('/api/search-audit-trail',{query}).then(x=>setEntries(x.entries||[])).catch(e=>notify(e.message));useEffect(()=>{search()},[]);return <><section className="section-intro split"><div><p className="eyebrow">IMMUTABLE RECORD</p><h2>Audit trail</h2><p>Search sign-ins, offers, custody, capacity, exceptions, and completion events.</p></div><div className="search"><input aria-label="Search audit history" placeholder="Search audit history" value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()}/><button className="secondary" onClick={search}>Search</button></div></section><section className="panel table-panel"><table><thead><tr><th>Time</th><th>Action</th><th>Actor / role</th><th>Entity</th><th>Outcome</th></tr></thead><tbody>{entries.map((x:Any)=><tr key={x.auditId}><td>{fmt(x.occurredAt)}</td><td><strong>{statusLabel(x.action)}</strong></td><td>{x.actorId?.slice(0,10)||'System'}<small>{x.role}</small></td><td>{x.entityType} · {x.entityId?.slice(0,10)}</td><td><span className="fresh">Success</span></td></tr>)}{!entries.length&&<tr><td colSpan={5}><Empty title="No audit records" text="Matching events will appear here."/></td></tr>}</tbody></table></section></>}

createRoot(document.getElementById('root')!).render(<App/>);
"}

