{"command":"str_replace","path":"/workspace/backend/server.go","old_str":"func (s *Server) route(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path == "/ready" {","new_str":"func (s *Server) route(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/ready" && !strings.HasPrefix(r.URL.Path, "/api/") {
		file := filepath.Join("frontend", "dist", r.URL.Path)
		if r.URL.Path == "/" { file = filepath.Join("frontend", "dist", "index.html") }
		if _, err := os.Stat(file); err != nil { file = filepath.Join("frontend", "dist", "index.html") }
		http.ServeFile(w, r, file)
